import { createGrammarLesson } from '../../../schemas/index.js';

const level = 'A1';
const status = 'ready';
function q(question, options, answer, explanation = '', context = '') { return { question, options, answer, explanation, context }; }
function ex(english, translation, why, warning = '') { return { english, translation, why, warning }; }
function mistake(wrong, right, why, howToAvoid, miniPractice = '') { return { wrong, right, why, howToAvoid, miniPractice }; }
function task(instruction, note = '', expected = '') { return { instruction, note, expected }; }
function step(text, note = '') { return { text, note }; }

function commonToBeExamples(kind) {
  const affirmative = kind === 'affirmative';
  const negative = kind === 'negative';
  const questions = kind === 'questions';
  const shortAnswers = kind === 'shortAnswers';
  if (affirmative) return [
    ex('I am a student.', 'Eu sou estudante.', 'I combina com am. A frase liga o sujeito I à informação a student.', 'Não diga “I is”.'),
    ex('You are ready.', 'Você está pronto.', 'You combina com are, mesmo quando significa você no singular.', 'Não diga “you is”.'),
    ex('He is my brother.', 'Ele é meu irmão.', 'He é terceira pessoa singular; por isso usamos is.', 'Não use are com he.'),
    ex('She is from Brazil.', 'Ela é do Brasil.', 'She pede is e a informação depois mostra origem.', 'Não traduza como “She has from Brazil”.'),
    ex('It is my phone.', 'É meu celular.', 'It funciona como sujeito para coisa/objeto.', 'Não comece direto com is.'),
    ex('We are friends.', 'Nós somos amigos.', 'We é plural/inclui o falante, então usa are.', 'Não diga “we is”.'),
    ex('They are teachers.', 'Eles são professores.', 'They representa grupo e combina com are.', 'Não diga “they is”.'),
    ex('My name is Ana.', 'Meu nome é Ana.', 'My name é o sujeito; por ser singular, usa is.', 'Não diga “my name are”.'),
    ex('My parents are here.', 'Meus pais estão aqui.', 'Parents é plural, então usa are.', 'Não use is com plural.'),
    ex('This book is new.', 'Este livro é novo.', 'This book é singular, então is.', 'Não use are só porque a frase parece descritiva.'),
    ex('The books are new.', 'Os livros são novos.', 'The books é plural, então are.', 'Não use is com books.'),
    ex('Brazil is big.', 'O Brasil é grande.', 'Brazil é um país singular, então is.', 'País/lugar no singular usa is.'),
  ];
  if (negative) return [
    ex('I am not tired.', 'Eu não estou cansado.', 'A negação com to be coloca not depois de am.', 'Não diga “I not am”.'),
    ex('You are not late.', 'Você não está atrasado.', 'Not vem depois de are.', 'Não use don’t com to be neste padrão.'),
    ex('He is not my teacher.', 'Ele não é meu professor.', 'Not vem depois de is e antes da informação.', 'Não diga “He not is”.'),
    ex('She is not from Canada.', 'Ela não é do Canadá.', 'A ordem é she + is + not + informação.', 'Não coloque not antes de is.'),
    ex('It is not my phone.', 'Não é meu celular.', 'It é o sujeito e not nega a ligação feita por is.', 'Não comece com “Is not my phone” no A1 afirmativo/negativo.'),
    ex('We are not ready.', 'Nós não estamos prontos.', 'We combina com are; not vem depois.', 'Não diga “we not are”.'),
    ex('They are not students.', 'Eles não são estudantes.', 'They + are + not forma a negativa.', 'Não diga “they is not”.'),
    ex('My name is not Lucas.', 'Meu nome não é Lucas.', 'My name é singular, então is not.', 'Não use are not.'),
    ex('My parents are not here.', 'Meus pais não estão aqui.', 'Parents é plural, então are not.', 'Não use is not com plural.'),
    ex('The book is not blue.', 'O livro não é azul.', 'Book é singular; is not nega a descrição.', 'Não confunda com do not.'),
    ex('The books are not old.', 'Os livros não são velhos.', 'Books é plural; are not nega a descrição.', 'Não use is not.'),
    ex('Brazil is not small.', 'O Brasil não é pequeno.', 'País singular usa is not.', 'Não use are not com Brazil.'),
  ];
  if (questions) return [
    ex('Are you ready?', 'Você está pronto?', 'Em perguntas com to be, are vai antes de you.', 'Não diga “Do you are ready?”.'),
    ex('Is he your brother?', 'Ele é seu irmão?', 'Is vem antes de he porque é pergunta com to be.', 'Não mantenha “He is your brother?” como padrão principal.'),
    ex('Is she from Brazil?', 'Ela é do Brasil?', 'She combina com is, e is abre a pergunta.', 'Não use are com she.'),
    ex('Is it your phone?', 'É seu celular?', 'It representa o objeto, e is começa a pergunta.', 'Não comece com “Do it is”.'),
    ex('Are we late?', 'Estamos atrasados?', 'We combina com are; na pergunta, are vem primeiro.', 'Não use is we.'),
    ex('Are they students?', 'Eles são estudantes?', 'They combina com are, então are abre a pergunta.', 'Não use is they.'),
    ex('Am I late?', 'Eu estou atrasado?', 'Com I, a pergunta começa com am.', 'É menos frequente, mas correto.'),
    ex('Is your name Ana?', 'Seu nome é Ana?', 'Your name é singular; a pergunta começa com is.', 'Não use are your name.'),
    ex('Are your parents here?', 'Seus pais estão aqui?', 'Parents é plural, então a pergunta começa com are.', 'Não use is.'),
    ex('Is this book new?', 'Este livro é novo?', 'This book é singular; use is.', 'Não use are com singular.'),
    ex('Are the books new?', 'Os livros são novos?', 'Books é plural; use are.', 'Não use is com plural.'),
    ex('Is Brazil big?', 'O Brasil é grande?', 'Brazil é singular; use is.', 'Não use do nesta pergunta com to be.'),
  ];
  if (shortAnswers) return [
    ex('Are you ready? Yes, I am.', 'Você está pronto? Sim, estou.', 'A pergunta usa are you, mas a resposta fala de I, então I am.', 'Não responda “Yes, I are”.'),
    ex('Are you ready? No, I am not.', 'Você está pronto? Não, não estou.', 'A resposta negativa mantém am not com I.', 'Não use don’t.'),
    ex('Is he your brother? Yes, he is.', 'Ele é seu irmão? Sim, é.', 'A resposta repete o pronome he e o verbo is.', 'Não diga “Yes, he do”.'),
    ex('Is she from Brazil? No, she is not.', 'Ela é do Brasil? Não, não é.', 'Pergunta com is pede resposta com is/is not.', 'Não use are.'),
    ex('Is it your phone? Yes, it is.', 'É seu celular? Sim, é.', 'It retoma o objeto da pergunta.', 'Não responda só “yes” quando estiver treinando A1.'),
    ex('Are we late? No, we are not.', 'Estamos atrasados? Não, não estamos.', 'We combina com are na resposta.', 'Não diga “we is not”.'),
    ex('Are they students? Yes, they are.', 'Eles são estudantes? Sim, são.', 'They combina com are.', 'Não use is.'),
    ex('Am I late? No, you are not.', 'Estou atrasado? Não, você não está.', 'A pessoa responde sobre you porque está falando com quem perguntou.', 'Não responda “No, I am not” se quem pergunta é outra pessoa e você responde a ela.'),
    ex('Is your name Ana? Yes, it is.', 'Seu nome é Ana? Sim, é.', 'It retoma a ideia “your name”.', 'Também é comum responder “Yes, my name is Ana”.'),
    ex('Are your parents here? No, they are not.', 'Seus pais estão aqui? Não, não estão.', 'Parents vira they na resposta.', 'Não use he/she para parents.'),
    ex('Is this book new? Yes, it is.', 'Este livro é novo? Sim, é.', 'Book vira it na resposta curta.', 'Não use he/she.'),
    ex('Are the books new? No, they are not.', 'Os livros são novos? Não, não são.', 'Books é plural; use they are not.', 'Não use it para plural.'),
  ];
  return [];
}

function makeToBeLesson({ id, order, title, kind, tags, pattern, goal, opening, why, concept, bridge, useCases, formation, whenUse, whenNot, guidedBeforeQuiz, mistakes, guided, errors, transforms, translations, production, recap }) {
  return createGrammarLesson({
    id, level, order, title, status, estimatedMinutes: 60,
    tags: tags || ['a1', 'grammar', 'be-verb', kind, 'beginner-foundation'],
    objectives: [
      `Entender a lógica de ${title}.`,
      'Aplicar a regra em frases A1 sem traduzir palavra por palavra.',
      'Reconhecer e corrigir erros comuns de brasileiros.',
      'Produzir frases próprias com segurança antes de avançar.',
    ],
    teacherOpening: opening,
    whyItMatters: why,
    realLifeUseCases: useCases,
    conceptExplanation: concept,
    mentalModel: { title: pattern, summary: 'Pense no sujeito, escolha a forma correta do to be e depois complete a informação. A ordem muda quando a frase é pergunta ou negativa.', steps: formation.map((item) => item.instruction || item.text || String(item)) },
    stepByStep: [
      step('Identifique o sujeito da frase.', 'I, you, he, she, it, we, they, um nome singular ou um plural.'),
      step('Escolha a forma correta do verb to be.', 'I am; he/she/it is; you/we/they are.'),
      step('Aplique a ordem do tipo de frase.', 'Afirmativa, negativa, pergunta ou resposta curta têm ordens diferentes.'),
      step('Complete com a informação.', 'Nome, profissão, origem, lugar, estado ou descrição.'),
      step('Revise o erro brasileiro mais provável.', 'Não pule sujeito, não use do com to be e não misture am/is/are.'),
    ],
    portugueseContrast: [
      task('Português esconde muita informação no verbo; inglês normalmente exige sujeito visível.', 'Por isso dizemos I am, she is, they are.'),
      task('Português permite “sou”, “é”, “estão”; inglês precisa separar sujeito e verbo.', 'O aluno deve pensar em blocos: I am / she is / they are.'),
      task('Em português a ordem da pergunta pode ser só entonação; em inglês com to be a ordem muda.', 'You are ready → Are you ready?'),
      task('Em português usamos “não” antes do verbo principal; em inglês com to be, not vem depois de am/is/are.', 'I am not, she is not, they are not.'),
    ],
    guidedDiscovery: [
      task('Compare: “I am ready” e “Are you ready?” O que mudou?', 'Na pergunta, are foi para o começo.'),
      task('Compare: “She is here” e “She is not here.” Onde entrou a negação?', 'Not entrou depois de is.'),
      task('Compare: “Are they students?” e “Yes, they are.” O que a resposta curta reaproveita?', 'Reaproveita pronome + forma correta do to be.'),
    ],
    guidedBeforeQuiz,
    grammarGoal: goal,
    formationGuide: formation,
    whenToUse: whenUse,
    whenNotToUse: whenNot,
    grammarTable: [
      { label: 'I', pattern: 'I am', example: kind === 'questions' ? 'Am I late?' : 'I am ready.', note: 'I combina com am.' },
      { label: 'he / she / it', pattern: 'he/she/it is', example: 'She is here.', note: 'Terceira pessoa singular usa is.' },
      { label: 'you / we / they', pattern: 'you/we/they are', example: 'They are students.', note: 'You, we e they usam are.' },
      { label: 'negative', pattern: 'subject + am/is/are + not', example: 'She is not here.', note: 'Not vem depois do to be.' },
      { label: 'question', pattern: 'am/is/are + subject', example: 'Are you ready?', note: 'To be vem antes do sujeito.' },
    ],
    teacherExamples: commonToBeExamples(kind),
    commonBrazilianMistakes: mistakes,
    controlledPractice: formation.slice(0, 6),
    guidedPractice: guided,
    errorCorrectionPractice: errors,
    transformationPractice: transforms,
    translationPractice: translations,
    productionTasks: production,
    selfAssessment: [
      task('Consigo explicar a regra sem olhar?'),
      task('Consigo dizer por que a ordem muda?'),
      task('Consigo corrigir o erro brasileiro mais comum desta aula?'),
      task('Consigo criar frases próprias usando o padrão?'),
    ],
    lessonRecap: recap,
    nextLessonBridge: bridge,
    masteryCriteria: { minPracticeAccuracy: 80, requiredProduction: 3, tags: ['a1-grammar', kind, 'deep-approved-target'] },
  });
}

