    guided: [q('Transforme em pergunta: You are ready.', ['Are you ready?','You are ready?','Do you are ready?'], 'Are you ready?', 'Are vem antes de you.'), q('Complete: ___ she your sister?', ['Are','Am','Is'], 'Is', 'She usa is.'), q('Complete: ___ they students?', ['Is','Are','Am'], 'Are', 'They usa are.'), q('Complete: ___ it your phone?', ['Is','Are','Do'], 'Is', 'It usa is; sem do.'), q('Complete: ___ I late?', ['Am','Are','Is'], 'Am', 'I usa am em pergunta.'), q('Qual pergunta está correta?', ['Do you are from Brazil?','Are you from Brazil?','You are from Brazil?'], 'Are you from Brazil?', 'To be vem antes do sujeito.'), q('Complete: ___ your parents here?', ['Is','Are','Am'], 'Are', 'Parents é plural.'), q('Complete: ___ this book new?', ['Are','Is','Am'], 'Is', 'This book é singular.')],
    errors: [q('Corrija: Do you are happy?', ['Are you happy?','Do you happy?','You are happy?'], 'Are you happy?', 'Não use do com to be.'), q('Corrija: Is they ready?', ['Are they ready?','They are ready?','Am they ready?'], 'Are they ready?', 'They usa are.'), q('Corrija: Are she here?', ['Is she here?','She is here?','Are here she?'], 'Is she here?', 'She usa is.'), q('Corrija: Do it is blue?', ['Is it blue?','It is blue?','Are it blue?'], 'Is it blue?', 'It usa is.')],
    transforms: [q('Transforme: She is a student.', ['Is she a student?','She is a student?','Are she a student?'], 'Is she a student?', 'Is antes de she.'), q('Transforme: They are friends.', ['Are they friends?','Is they friends?','They are friends?'], 'Are they friends?', 'Are antes de they.'), q('Transforme: It is your book.', ['Is it your book?','Are it your book?','Do it is your book?'], 'Is it your book?', 'Is antes de it.'), q('Transforme: We are late.', ['Are we late?','Is we late?','Do we are late?'], 'Are we late?', 'Are antes de we.')],
