    mistakes: [mistake('Are you ready? Yes, I do.', 'Are you ready? Yes, I am.', 'A pergunta usa are, então a resposta usa to be, não do.', 'Pergunta com to be pede resposta com to be.', 'Yes, I ___.'), mistake('Is she here? Yes, she are.', 'Is she here? Yes, she is.', 'She combina com is.', 'Repita pronome + verbo correto.', 'Yes, she ___.'), mistake('Are they students? Yes, they is.', 'Are they students? Yes, they are.', 'They combina com are.', 'They are.', 'Yes, they ___.'), mistake('Are you late? Yes, you are.', 'Are you late? Yes, I am.', 'Quem responde fala de si mesmo.', 'You da pergunta vira I na resposta.', 'Yes, ___ am.'), mistake('Is it your book? Yes, he is.', 'Is it your book? Yes, it is.', 'Book/it é objeto.', 'Use it para objeto.', 'Yes, it ___.'), mistake('Are your parents here? Yes, he is.', 'Are your parents here? Yes, they are.', 'Parents é plural.', 'Use they are.', 'Yes, they ___.'), mistake('Am I late? No, I am not.', 'Am I late? No, you are not.', 'Se outra pessoa pergunta “Am I late?”, você responde sobre ela: you.', 'Observe quem está falando.', 'No, you ___ not.'), mistake('Is this book new? No, they are not.', 'Is this book new? No, it is not.', 'This book é singular.', 'Singular objeto vira it.', 'No, it ___ not.')],
    guided: [q('Resposta para “Are you ready?”', ['Yes, I am.','Yes, I are.','Yes, I do.'], 'Yes, I am.', 'You da pergunta vira I na resposta.'), q('Resposta para “Is she here?”', ['Yes, she is.','Yes, she are.','Yes, she do.'], 'Yes, she is.', 'She usa is.'), q('Resposta para “Are they students?”', ['Yes, they are.','Yes, they is.','Yes, they do.'], 'Yes, they are.', 'They usa are.'), q('Resposta para “Is it your phone?”', ['No, it is not.','No, he is not.','No, it are not.'], 'No, it is not.', 'Objeto usa it is not.'), q('Complete: Are we late? No, we ___.', ['are not','is not','am not'], 'are not', 'We usa are.'), q('Complete: Am I late? No, you ___ not.', ['am','is','are'], 'are', 'Quem responde diz you are not.'), q('Complete: Is your name Ana? Yes, it ___.', ['are','is','am'], 'is', 'Your name pode virar it.'), q('Complete: Are your parents here? No, they ___ not.', ['is','are','am'], 'are', 'Parents vira they are not.')],
    errors: [q('Corrija: Yes, I do.', ['Yes, I am.','Yes, I are.','Yes, I is.'], 'Yes, I am.', 'Para “Are you...?”, use I am.'), q('Corrija: No, she are not.', ['No, she is not.','No, she am not.','No, she do not.'], 'No, she is not.', 'She usa is.'), q('Corrija: Yes, they is.', ['Yes, they are.','Yes, they am.','Yes, they do.'], 'Yes, they are.', 'They usa are.'), q('Corrija: Is it your book? Yes, he is.', ['Yes, it is.','Yes, she is.','Yes, they are.'], 'Yes, it is.', 'Book vira it.')],
